#!/usr/bin/env node
/**
 * Super Admin Credential Generator for Skidspace.com
 * Generates secure production credentials for GCP deployment
 * Generated by Swarm Coordination Team - 2026-03-24
 */

import crypto from 'crypto';
import bcryptjs from 'bcryptjs';
import { v4 as uuidv4 } from 'uuid';
import fs from 'fs/promises';
import path from 'path';
import { fileURLToPath } from 'url';

// Use bcryptjs instead of bcrypt for better compatibility
const bcrypt = bcryptjs;

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Security configuration
const BCRYPT_ROUNDS = 12;
const PASSWORD_LENGTH = 32;
const SECRET_LENGTH = 64;
const MASTER_KEY_LENGTH = 32;

class SuperAdminCredentialGenerator {
  constructor() {
    this.credentials = {};
    this.outputPath = path.join(__dirname, '../config');
    this.timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  }

  /**
   * Generate cryptographically secure random string
   */
  generateSecureRandom(length, charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()') {
    const array = new Uint8Array(length * 2);
    crypto.getRandomValues(array);

    let result = '';
    for (let i = 0; i < length; i++) {
      result += charset[array[i] % charset.length];
    }

    return result;
  }

  /**
   * Generate secure password with specific requirements
   */
  generateSecurePassword() {
    const lowercase = 'abcdefghijklmnopqrstuvwxyz';
    const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    const numbers = '0123456789';
    const symbols = '!@#$%^&*()_+-=[]{}|;:,.<>?';
    const allChars = lowercase + uppercase + numbers + symbols;

    // Ensure at least one character from each set
    let password = '';
    password += lowercase[Math.floor(Math.random() * lowercase.length)];
    password += uppercase[Math.floor(Math.random() * uppercase.length)];
    password += numbers[Math.floor(Math.random() * numbers.length)];
    password += symbols[Math.floor(Math.random() * symbols.length)];

    // Fill the rest randomly
    for (let i = 4; i < PASSWORD_LENGTH; i++) {
      password += allChars[Math.floor(Math.random() * allChars.length)];
    }

    // Shuffle the password
    return password.split('').sort(() => Math.random() - 0.5).join('');
  }

  /**
   * Generate organization and user IDs
   */
  generateIds() {
    return {
      organizationId: uuidv4(),
      userId: uuidv4(),
      sessionId: uuidv4(),
    };
  }

  /**
   * Generate all required credentials
   */
  async generateCredentials() {
    console.log('🔐 Generating Super Admin Credentials for Skidspace.com Production...\n');

    const ids = this.generateIds();
    const plainPassword = this.generateSecurePassword();
    const passwordHash = await bcrypt.hash(plainPassword, BCRYPT_ROUNDS);

    this.credentials = {
      // Identity
      ids,
      superAdminEmail: 'admin@skidspace.com',
      plainPassword, // Store temporarily for GCP Secret Manager
      passwordHash,

      // Security tokens
      nextAuthSecret: this.generateSecureRandom(SECRET_LENGTH),
      platformMasterKey: crypto.randomBytes(MASTER_KEY_LENGTH).toString('hex'),
      superAdminCode: this.generateSecureRandom(16, '0123456789ABCDEF'),
      csrfSecret: this.generateSecureRandom(SECRET_LENGTH),
      encryptionKey: crypto.randomBytes(32).toString('hex'),
      jwtSecret: this.generateSecureRandom(SECRET_LENGTH),

      // API keys
      healthCheckSecret: this.generateSecureRandom(32),
      webhookSecret: this.generateSecureRandom(32),

      // Database credentials
      dbPassword: this.generateSecureRandom(32, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'),

      // Generation metadata
      generatedAt: new Date().toISOString(),
      version: '1.0.0',
      environment: 'production'
    };

    return this.credentials;
  }

  /**
   * Create GCP Secret Manager compatible format
   */
  generateGCPSecrets() {
    const secrets = {
      'skidspace-super-admin-credentials': {
        email: this.credentials.superAdminEmail,
        password: this.credentials.plainPassword,
        passwordHash: this.credentials.passwordHash,
        organizationId: this.credentials.ids.organizationId,
        userId: this.credentials.ids.userId,
        generatedAt: this.credentials.generatedAt
      },
      'skidspace-application-secrets': {
        nextAuthSecret: this.credentials.nextAuthSecret,
        platformMasterKey: this.credentials.platformMasterKey,
        superAdminCode: this.credentials.superAdminCode,
        csrfSecret: this.credentials.csrfSecret,
        encryptionKey: this.credentials.encryptionKey,
        jwtSecret: this.credentials.jwtSecret
      },
      'skidspace-api-keys': {
        healthCheckSecret: this.credentials.healthCheckSecret,
        webhookSecret: this.credentials.webhookSecret
      },
      'skidspace-database-credentials': {
        password: this.credentials.dbPassword,
        host: '${DB_HOST}',
        name: 'skidspace_production',
        user: 'skidspace_prod_user'
      }
    };

    return secrets;
  }

  /**
   * Generate environment variable template
   */
  generateEnvTemplate() {
    return `# Skidspace Production Environment Variables
# Generated: ${this.credentials.generatedAt}
# SECURITY WARNING: Store these values in GCP Secret Manager

# Super Admin Credentials
export SUPER_ADMIN_EMAIL="${this.credentials.superAdminEmail}"
export SUPER_ADMIN_PASSWORD_HASH="${this.credentials.passwordHash}"
export SUPER_ADMIN_SECURITY_CODE="${this.credentials.superAdminCode}"

# Application Secrets
export NEXTAUTH_SECRET="${this.credentials.nextAuthSecret}"
export PLATFORM_MASTER_KEY="${this.credentials.platformMasterKey}"
export AES_256_ENCRYPTION_KEY="${this.credentials.encryptionKey}"
export CSRF_SECRET="${this.credentials.csrfSecret}"
export JWT_SECRET="${this.credentials.jwtSecret}"

# API Security
export HEALTH_CHECK_SECRET="${this.credentials.healthCheckSecret}"
export WEBHOOK_SECRET="${this.credentials.webhookSecret}"

# Database
export DB_PASSWORD="${this.credentials.dbPassword}"

# Organization & User IDs
export PLATFORM_ORG_ID="${this.credentials.ids.organizationId}"
export SUPER_ADMIN_USER_ID="${this.credentials.ids.userId}"
`;
  }

  /**
   * Generate database initialization SQL
   */
  generateDatabaseInitSQL() {
    return `-- Skidspace Production Database Initialization
-- Generated: ${this.credentials.generatedAt}
-- Super Admin Setup

BEGIN;

-- Create platform organization
INSERT INTO organizations (
  id,
  name,
  slug,
  type,
  status,
  settings,
  created_at,
  updated_at
) VALUES (
  '${this.credentials.ids.organizationId}',
  'Skidspace Platform',
  'platform',
  'PLATFORM',
  'ACTIVE',
  '{"isPlatform": true, "maxUsers": 10000}',
  NOW(),
  NOW()
);

-- Create super admin user
INSERT INTO users (
  id,
  email,
  email_verified,
  name,
  password,
  organization_id,
  status,
  preferences,
  created_at,
  updated_at,
  last_login_at
) VALUES (
  '${this.credentials.ids.userId}',
  '${this.credentials.superAdminEmail}',
  NOW(),
  'Platform Administrator',
  '${this.credentials.passwordHash}',
  '${this.credentials.ids.organizationId}',
  'ACTIVE',
  '{"theme": "system", "notifications": true}',
  NOW(),
  NOW(),
  NULL
);

-- Create super admin role
INSERT INTO roles (
  id,
  name,
  slug,
  description,
  organization_id,
  level,
  is_system,
  is_default,
  color,
  icon,
  created_at,
  updated_at
) VALUES (
  '${uuidv4()}',
  'Super Administrator',
  'super-admin',
  'Platform super administrator with full system access',
  '${this.credentials.ids.organizationId}',
  100,
  true,
  false,
  '#DC2626',
  'shield-check',
  NOW(),
  NOW()
);

-- Create platform permissions
INSERT INTO permissions (name, slug, description, category, organization_id, is_system, created_at, updated_at)
VALUES
  ('Platform Administration', 'platform:admin', 'Full platform administration access', 'platform', '${this.credentials.ids.organizationId}', true, NOW(), NOW()),
  ('User Management', 'users:manage', 'Create, read, update, delete users', 'users', '${this.credentials.ids.organizationId}', true, NOW(), NOW()),
  ('Organization Management', 'organizations:manage', 'Manage all organizations', 'organizations', '${this.credentials.ids.organizationId}', true, NOW(), NOW()),
  ('Warehouse Management', 'warehouses:manage', 'Manage all warehouses', 'warehouses', '${this.credentials.ids.organizationId}', true, NOW(), NOW()),
  ('System Configuration', 'system:config', 'Configure system settings', 'system', '${this.credentials.ids.organizationId}', true, NOW(), NOW()),
  ('Audit Access', 'audit:read', 'Read audit logs', 'audit', '${this.credentials.ids.organizationId}', true, NOW(), NOW());

-- Assign super admin role to user
INSERT INTO user_roles (
  id,
  user_id,
  role_id,
  assigned_by,
  assigned_at
) VALUES (
  '${uuidv4()}',
  '${this.credentials.ids.userId}',
  (SELECT id FROM roles WHERE slug = 'super-admin' AND organization_id = '${this.credentials.ids.organizationId}'),
  '${this.credentials.ids.userId}',
  NOW()
);

-- Assign all permissions to super admin role
INSERT INTO role_permissions (id, role_id, permission_id)
SELECT
  gen_random_uuid(),
  (SELECT id FROM roles WHERE slug = 'super-admin' AND organization_id = '${this.credentials.ids.organizationId}'),
  p.id
FROM permissions p
WHERE p.organization_id = '${this.credentials.ids.organizationId}';

-- Create system configuration entries
INSERT INTO system_config (id, key, value, description, category, created_at, updated_at)
VALUES
  ('${uuidv4()}', 'platform.initialized', 'true', 'Platform initialization status', 'system', NOW(), NOW()),
  ('${uuidv4()}', 'platform.version', '"1.0.0"', 'Current platform version', 'system', NOW(), NOW()),
  ('${uuidv4()}', 'security.mfa_required', 'true', 'Require MFA for admin users', 'security', NOW(), NOW()),
  ('${uuidv4()}', 'security.session_timeout', '86400', 'Session timeout in seconds', 'security', NOW(), NOW());

-- Create initial audit log entry
INSERT INTO audit_logs (
  id,
  user_id,
  organization_id,
  action,
  resource,
  status,
  details,
  created_at
) VALUES (
  '${uuidv4()}',
  '${this.credentials.ids.userId}',
  '${this.credentials.ids.organizationId}',
  'system.initialize',
  'platform',
  'success',
  '{"message": "Platform initialized with super admin user", "version": "1.0.0"}',
  NOW()
);

COMMIT;

-- Verify installation
SELECT
  u.email,
  u.name,
  o.name as organization,
  r.name as role,
  COUNT(p.id) as permissions_count
FROM users u
JOIN organizations o ON u.organization_id = o.id
JOIN user_roles ur ON u.id = ur.user_id
JOIN roles r ON ur.role_id = r.id
LEFT JOIN role_permissions rp ON r.id = rp.role_id
LEFT JOIN permissions p ON rp.permission_id = p.id
WHERE u.email = '${this.credentials.superAdminEmail}'
GROUP BY u.email, u.name, o.name, r.name;
`;
  }

  /**
   * Save all generated files
   */
  async saveCredentials() {
    await fs.mkdir(this.outputPath, { recursive: true });

    const timestamp = this.timestamp;

    // Save GCP secrets
    const gcpSecrets = this.generateGCPSecrets();
    await fs.writeFile(
      path.join(this.outputPath, `gcp-secrets-${timestamp}.json`),
      JSON.stringify(gcpSecrets, null, 2)
    );

    // Save environment template
    const envTemplate = this.generateEnvTemplate();
    await fs.writeFile(
      path.join(this.outputPath, `production-env-${timestamp}.sh`),
      envTemplate
    );

    // Save database initialization
    const dbInitSQL = this.generateDatabaseInitSQL();
    await fs.writeFile(
      path.join(this.outputPath, `database-init-${timestamp}.sql`),
      dbInitSQL
    );

    // Save credentials summary (for secure storage)
    const summary = {
      ...this.credentials,
      plainPassword: '[REDACTED - Check GCP Secret Manager]' // Don't store plain password in summary
    };
    await fs.writeFile(
      path.join(this.outputPath, `credentials-summary-${timestamp}.json`),
      JSON.stringify(summary, null, 2)
    );

    return {
      gcpSecretsFile: `gcp-secrets-${timestamp}.json`,
      envTemplateFile: `production-env-${timestamp}.sh`,
      dbInitFile: `database-init-${timestamp}.sql`,
      summaryFile: `credentials-summary-${timestamp}.json`
    };
  }

  /**
   * Generate secure login credentials for immediate use
   */
  getLoginCredentials() {
    return {
      url: 'https://admin.skidspace.com/auth/signin',
      email: this.credentials.superAdminEmail,
      password: this.credentials.plainPassword,
      organizationSlug: 'platform',
      securityCode: this.credentials.superAdminCode,
      userId: this.credentials.ids.userId,
      organizationId: this.credentials.ids.organizationId
    };
  }

  /**
   * Display credentials securely
   */
  displayCredentials() {
    const loginCreds = this.getLoginCredentials();

    console.log('🎉 Super Admin Credentials Generated Successfully!\n');
    console.log('📋 IMMEDIATE LOGIN CREDENTIALS (Store Securely):');
    console.log('═'.repeat(60));
    console.log(`🌐 Login URL: ${loginCreds.url}`);
    console.log(`📧 Email: ${loginCreds.email}`);
    console.log(`🔑 Password: ${loginCreds.password}`);
    console.log(`🏢 Organization: ${loginCreds.organizationSlug}`);
    console.log(`🛡️ Security Code: ${loginCreds.securityCode}`);
    console.log('═'.repeat(60));
    console.log('\n🔐 SYSTEM IDENTIFIERS:');
    console.log(`👤 User ID: ${loginCreds.userId}`);
    console.log(`🏢 Org ID: ${loginCreds.organizationId}`);
    console.log('\n⚠️  SECURITY WARNINGS:');
    console.log('• Change the default password after first login');
    console.log('• Enable MFA immediately');
    console.log('• Store credentials in GCP Secret Manager');
    console.log('• Delete local credential files after deployment');
    console.log('• Monitor admin account activity regularly');

    return loginCreds;
  }
}

// Execute if run directly
if (import.meta.url === `file://${process.argv[1]}`) {
  const generator = new SuperAdminCredentialGenerator();

  try {
    await generator.generateCredentials();
    const files = await generator.saveCredentials();
    const loginCreds = generator.displayCredentials();

    console.log('\n📁 Generated Files:');
    Object.entries(files).forEach(([key, filename]) => {
      console.log(`${key}: ${filename}`);
    });

    console.log('\n✅ Production credentials ready for deployment!');

  } catch (error) {
    console.error('❌ Error generating credentials:', error);
    process.exit(1);
  }
}

export default SuperAdminCredentialGenerator;